{
  "kind": "agentops.validation",
  "schemaVersion": "agentops.workflow-dsl@2.0.0",
  "validators": [
    {
      "id": "validator.intake-checks",
      "purpose": "Intake binds exact frozen design identity, authority order and working Obligation Register; derivable facts investigated rather than converted into questions; no ambient design/current-file substitution; non-ready or contradictory design fails closed.",
      "input": "intake result and state",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.preflight-checks",
      "purpose": "Preflight verifies clean worktree, design status/identity, project-native build/test/coverage/static commands, safe test isolation, obligation classification completeness, Contract availability facts and tool/permission availability; unsafe/unclassified/unmeasurable conditions cannot be waived by an Agent.",
      "input": "preflight result and repository state",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.feasibility-checks",
      "purpose": "Every IMPLEMENTATION_FEASIBILITY obligation has a conclusive compatible result and selected binding from the frozen Harness feasibility phase; inconclusive evidence stays in IM-02V; a result that invalidates the frozen design stops the Delivery.",
      "input": "feasibility evidence records",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.grilling-checks",
      "purpose": "Grilling asked one decision at a time and investigated facts first; every Goal has classification, dependency, Oracle, Test Ladder and completion relation; measurement authority established without architecture decisions.",
      "input": "grilling result and goal packets",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.goal-graph-checks",
      "purpose": "Every upstream obligation mapped to a Goal, feasibility result, external blocker or operational handoff; no unresolved user decision remains; the Goal Graph is confirmed and frozen by the human.",
      "input": "goal graph and confirmation",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.branch-checks",
      "purpose": "Feature branch activated from a clean baseline with the baseline commit recorded; no auto-stash, reset, merge or conflicting-branch reuse.",
      "input": "git state",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.selection-checks",
      "purpose": "Deterministic selector order: Harness prerequisite, minimum end-to-end Walking Skeleton, then topological Goal/Test Ladder order; Implementer preference cannot choose the next Goal; a missing Contract waits only when no independent Ready Goal remains.",
      "input": "goal graph and goal states",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.calibration-checks",
      "purpose": "Current behavior fails for the expected reason, or existing-green is challenged by a negative fixture/controlled mutant; a test file that merely exists is insufficient; flaky/skipped/misdirected/non-discriminating tests cannot enter implementation.",
      "input": "test feedback",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.evolve-checks",
      "purpose": "The smallest production-code change turns the calibrated RED into GREEN; no formal test/fixture/Harness/coverage/writer-policy changes; diagnostic probes stay ignored and non-authoritative; stubs bound to known Contracts only.",
      "input": "production diff and test feedback",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.coverage-checks",
      "purpose": "New/modified behavior-bearing branches require 100% coverage plus branch-specific assertions; historical coverage cannot regress; generated/non-behavioral/proven-unreachable exclusions require exact evidence and later Auditor admission.",
      "input": "coverage map and diff",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.refactor-checks",
      "purpose": "Refactor improves the current prototype without changing frozen behavior; no speculative abstraction, future feature, generic HA/transaction/retry machinery or unrelated cleanup; NO_REFACTOR_NEEDED is valid.",
      "input": "refactor diff and frozen behavior",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.rung-verify",
      "purpose": "Rung verification checks current tests, affected regression, writer policy, stub ledger and Action evidence against one Git baseline; a random rerun to obtain GREEN is prohibited.",
      "input": "test evidence and git baseline",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.review-isolation",
      "purpose": "Both review lenses started fresh from the same Goal candidate and remained isolated until the barrier closed; black-box lens did not inspect the implementation before its initial counterexample result froze; shared raw evidence does not equal shared conclusions.",
      "input": "session and barrier records",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.aggregation-rules",
      "purpose": "Aggregation preserved provenance, merged only clear common causes, detected conflicts, routed each Finding; no voting, no severity changes, no test/code edits and no Finding closure by the aggregator.",
      "input": "review results and aggregation output",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.resolution-checks",
      "purpose": "Resolution stayed strictly within the frozen Goal (test-side: tests/fixtures only; implementation-side: production code only); negative feedback order is failing executable test, deterministic rule, then structured semantic recheck; any requested semantic expansion stops the Delivery.",
      "input": "finding, treatment and candidate",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.recheck-checks",
      "purpose": "Only the original Finding lens closes its Finding against the exact treatment and new candidate in a fresh session; Implementer/Aggregator cannot close it; the Finding records its review scope and return Action so recovery cannot confuse the two loops.",
      "input": "finding disposition and recheck result",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.goal-commit-checks",
      "purpose": "All Goal rungs complete, local Findings closed, writer/scope clean, focused/affected regression/coverage green, no unauthorized stubs; commit only explicit approved paths with Goal identity; RED states remain checkpoints, never commits.",
      "input": "candidate, findings and git state",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.whole-scope-checks",
      "purpose": "Cross-Goal composition, shared state, final Project Context applicability, mapped implementation-verification obligations and full regression pass against the complete branch; Findings return through IM-13; no partial success.",
      "input": "branch, goal commits and regression evidence",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.final-checks",
      "purpose": "Terminal Gate: every in-scope Goal VERIFIED, all Findings disposition-valid, required Harness phases pass against the candidate, no unauthorized stub/debug artifact, process artifacts absent from Git, worktree clean, exact run-manifest/retention disposition valid; an unmeasured tuning value cannot be reported as passed; no push/PR/merge/deploy.",
      "input": "candidate, state and manifest",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.writer-policy",
      "purpose": "Writer policy compares the Action-start Git baseline with staged, unstaged, renamed, deleted and untracked paths; Test Designer writes formal tests only, Implementer writes production code only; no cross-writer edits.",
      "input": "git diff and policy",
      "output": "pass/fail",
      "deterministic": true
    },
    {
      "id": "validator.cli-checks",
      "purpose": "Package CLI outputs structured JSON, command/argv, exit status, checked identities and bounded stdout/stderr; frozen argv arrays and shell=false; CLI failure is never reinterpreted as success.",
      "input": "CLI results",
      "output": "pass/fail",
      "deterministic": true
    }
  ],
  "aggregation": [
    {
      "id": "aggregation.review",
      "parallelNode": "node.IM-12",
